(()=>{
const data={
 rainbow:{index:'01',category:'RAINBOW PARK · EL ORIGEN',title:'Aquí comienza<br>tu colección.',description:'Lotes residenciales distribuidos en Rainbow Park, al oeste de Ocala. Un vecindario con viviendas de distintos propietarios y desarrolladores, donde Next Fraga reúne su colección.',tags:['Lotes dispersos','Entorno residencial','Next Fraga'],image:'assets/ocala-concept.png',alt:'Imagen generada de un entorno residencial arbolado; no es una fotografía de los lotes',label:'VISUAL CONCEPTUAL / IMAGEN GENERADA',credit:'Imagen conceptual generada para esta demo',source:null,link:'#lotes',linkText:'Ver la colección',query:'Rainbow Park Ocala Florida',path:'M245 330Q220 275 245 240'},
 wec:{index:'02',category:'DEPORTE · HOSPITALIDAD · EVENTOS',title:'Una conexión<br>con el mundo.',description:'World Equestrian Center reúne competencias, hoteles, gastronomía y espacios para eventos. Un referente para entender la identidad ecuestre de Ocala.',tags:['Cultura ecuestre','Hospitalidad','Encuentro'],image:'assets/territory-wec.jpg',alt:'Exterior de The Equestrian Manor en World Equestrian Center',label:'THE EQUESTRIAN MANOR / WEC',credit:'Fotografía: World Equestrian Center',source:'https://worldequestriancenter.com/growth/',link:'https://worldequestriancenter.com/ocala-fl/',linkText:'Visitar sitio oficial del WEC',query:'World Equestrian Center Ocala',path:'M245 330Q335 170 460 172'},
 downtown:{index:'03',category:'CULTURA · GASTRONOMÍA · PASEOS',title:'El ritmo<br>de la ciudad.',description:'El centro histórico de Ocala reúne comercios, restaurantes y espacios para pasear alrededor de su plaza. Otra manera de descubrir la vida local, más allá del terreno.',tags:['Plaza histórica','Comercio local','Gastronomía'],image:'assets/territory-downtown.jpg',alt:'Plaza del centro histórico de Ocala con su quiosco y visitantes',label:'HISTORIC DOWNTOWN SQUARE / OCALA',credit:'Fotografía: Ocala / Marion County Visitors Bureau',source:'https://www.ocalamarion.com/blog/explore-historic-downtown-ocala/',link:'https://www.ocalamarion.com/blog/explore-historic-downtown-ocala/',linkText:'Visitar guía oficial de turismo',query:'Ocala Historic Downtown Square',path:'M245 330Q460 280 703 300'},
 nature:{index:'04',category:'AGUA · PAISAJE · TIEMPO AL AIRE LIBRE',title:'Cambia<br>de ritmo.',description:'Rainbow Springs, en Dunnellon, ofrece manantiales, senderos y actividades en el agua. Un destino regional para imaginar los días que también se viven fuera de casa.',tags:['Manantiales','Senderos','Kayak'],image:'assets/territory-nature.jpg',alt:'Aguas claras y vegetación de Rainbow Springs State Park',label:'RAINBOW SPRINGS STATE PARK / DUNNELLON',credit:'Fotografía: Ocala / Marion County Visitors Bureau',source:'https://www.ocalamarion.com/things-to-do/outdoors/parks/rainbow-springs-state-park/',link:'https://www.floridastateparks.org/parks-and-trails/rainbow-springs-state-park',linkText:'Visitar sitio oficial del parque',query:'Rainbow Springs State Park Dunnellon',path:'M245 330Q160 380 130 464'},
 airport:{index:'05',category:'CONECTIVIDAD · AVIACIÓN GENERAL',title:'Otra forma<br>de llegar.',description:'Ocala International Airport, al oeste de la ciudad, atiende aviación general, corporativa y carga. Una referencia para quienes llegan en aeronaves privadas o por viajes de negocio.',tags:['Aviación privada','Actividad corporativa','Ocala'],image:'assets/territory-airport.svg',alt:'Ilustración editorial de aviación; no representa las instalaciones del aeropuerto',label:'AVIACIÓN / ILUSTRACIÓN EDITORIAL',credit:'Información: City of Ocala · Ilustración conceptual',source:'https://www.ocalafl.gov/government/city-departments-i-z/ocala-international-airport',link:'https://www.ocalafl.gov/government/city-departments-i-z/ocala-international-airport',linkText:'Visitar sitio oficial del aeropuerto',query:'Ocala International Airport',path:'M245 330Q400 350 535 425'}
};
let selected='wec',mode='atlas';const $=id=>document.getElementById(id);
function mapUrl(){return 'https://www.google.com/maps?q='+encodeURIComponent(data[selected].query)+'&z=13&output=embed'}
function updateMap(){const d=data[selected];$('territory-iframe').title=`Ubicación de ${d.query} en Google Maps`;$('territory-iframe').src=mapUrl();$('territory-map-fallback').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(d.query)}
function select(key){selected=key;const d=data[key];document.querySelectorAll('[data-destination]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.destination===key)));$('destination-image').src=d.image;$('destination-image').alt=d.alt;$('destination-photo-label').textContent=d.label;$('destination-index').textContent=d.index+' / '+String(Object.keys(data).length).padStart(2,'0');$('destination-category').textContent=d.category;$('destination-title').innerHTML=d.title;$('destination-description').textContent=d.description;$('destination-tags').innerHTML=d.tags.map(t=>`<span>${t}</span>`).join('');const link=$('destination-link');link.innerHTML=d.linkText+' <span>↗</span>';link.href=d.link;const mapLink=$('destination-map-link');mapLink.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(d.query);mapLink.setAttribute('aria-label','Ver '+d.query+' en Google Maps (abre otra pestaña)');if(d.link.startsWith('#'))link.removeAttribute('target');else link.target='_blank';const credit=$('destination-credit');credit.textContent=d.credit;if(d.source){credit.href=d.source;credit.target='_blank'}else{credit.removeAttribute('href');credit.removeAttribute('target')}$('territory-connection').setAttribute('d',d.path);if(mode==='real')updateMap()}
document.querySelectorAll('[data-destination]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.destination)));
document.querySelectorAll('[data-territory-map]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.territoryMap;document.querySelectorAll('[data-territory-map]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$('territory-artboard').hidden=mode!=='atlas';$('territory-real-map').hidden=mode!=='real';if(mode==='real')updateMap()}));
document.querySelectorAll('.outlook-list details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.outlook-list details').forEach(x=>{if(x!==d)x.open=false})}));
})();
